#include "../src/RegistrationEnumeration.h"
#include <iostream>
#include <stdexcept>
#include <vector>
#include <cstring>
using namespace private_input::registration;
namespace {
unsigned checks=0,failures=0;
void check(bool value,const char*label){++checks;if(!value)throw std::runtime_error(label);}
void freshChildExit(){check(catalogChildExitResult(0)==0,"zero child result is success");for(auto code:{1u,2u,1168u,65536u})check(catalogChildExitResult(code)<0,"positive child exit must fail");check(catalogChildExitResult(0x80004005u)==EnumFailure,"failing HRESULT child result retained");check(catalogChildExitResult(0xc0000005u)==static_cast<std::int32_t>(0xc0000005u),"process fault retained");}
struct Step {std::int32_t hr;std::uint32_t fetched;int item;};
EnumerationDiagnostic run(std::vector<Step>steps,unsigned&calls,std::int32_t enumHR=EnumOk,bool available=true){
 return enumerateGuids<int>(14,enumHR,available,[&](int&item,std::uint32_t&fetched){check(calls<steps.size(),"unexpected extra Next call");const auto step=steps[calls++];item=step.item;fetched=step.fetched;return step.hr;},[](int item){return item==7?2u:0u;});
}
void normalEnd(){unsigned calls=0;auto value=run({{EnumEnd,0,0}},calls);check(value.result()==EnumOk,"S_FALSE/0 is successful empty enumeration");check(value.nextHR==EnumEnd&&value.items==0&&value.matches==0&&value.flags==(NextCalled|Complete),"empty state is explicit");check(value.requireMatches(2)==EnumFailure,"stage14 missing-category fatal guard remains");}
void oneAndEnd(){unsigned calls=0;auto value=run({{EnumOk,1,7},{EnumEnd,0,0}},calls);check(value.result()==EnumOk&&value.requireMatches(2)==EnumOk,"S_OK/1 item followed by S_FALSE/0 succeeds");check(value.items==1&&value.matches==2&&value.fetched==0&&calls==2,"exact item count and match retained");}
void nextFailure(){unsigned calls=0;auto value=run({{EnumFailure,0,0}},calls);check(value.result()==EnumFailure,"Next E_FAIL/0 must propagate rather than appear empty");check(value.nextHR==EnumFailure&&value.fetched==0&&value.items==0&&value.flags==NextCalled,"failed raw HRESULT and non-completion retained");}
void exactFailure(){constexpr auto denied=static_cast<std::int32_t>(0x80070005u);unsigned calls=0;auto value=run({{denied,0,0}},calls);check(value.result()==denied&&value.requireMatches(2)==denied,"exact Next error is preserved through fatal guard");}
void failureAfterMatch(){constexpr auto denied=static_cast<std::int32_t>(0x80070005u);unsigned calls=0;auto value=run({{EnumOk,1,7},{denied,0,0}},calls);check(value.items==1&&value.matches==2,"prior match retained for diagnosis");check(value.result()==denied&&value.requireMatches(2)==denied,"found item does not hide later enumeration failure");}
void malformed(){for(const auto step:std::vector<Step>{{EnumOk,0,7},{EnumOk,2,7},{EnumEnd,1,7},{2,0,7}}){unsigned calls=0;auto value=run({step},calls);check(value.result()==EnumUnexpected,"abnormal HRESULT/fetched pair must fail");check(value.items==0&&value.matches==0&&(value.flags&MalformedResult)&&!(value.flags&Complete),"malformed result is not consumed or called complete");}}
void failedAPICall(){constexpr auto denied=static_cast<std::int32_t>(0x80070005u);unsigned calls=0;auto value=run({},calls,denied,false);check(value.result()==denied&&value.enumerationHR==denied,"enumerator creation error preserved");check(value.nextHR==EnumNotCalled&&calls==0&&value.flags==0,"Next never called after failed API");}
void missingPointer(){unsigned calls=0;auto value=run({},calls,EnumOk,false);check(value.result()==EnumUnexpected,"successful API with null enumerator is not empty");check(calls==0&&value.flags==MissingEnumerator&&value.nextHR==EnumNotCalled,"null interface does not get dereferenced");}
void failureWithFetched(){unsigned calls=0;auto value=run({{EnumFailure,1,7}},calls);check(value.result()==EnumFailure&&value.fetched==1&&value.items==0&&value.matches==0,"failed HRESULT wins even if fetched is nonzero");}
void fixedNumericReceipt(){unsigned emptyCalls=0,errorCalls=0;auto empty=run({{EnumEnd,0,0}},emptyCalls),error=run({{EnumFailure,0,0}},errorCalls);check(empty.requireMatches(2)==EnumFailure&&error.requireMatches(2)==EnumFailure,"both original generic E_FAIL outcomes stay fatal");auto a=enumerationDiagnosticSuffix(empty),b=enumerationDiagnosticSuffix(error);check(a!=b&&a.find(".next-1.")!=std::string::npos&&b.find(".next-2147500037.")!=std::string::npos,"receipt distinguishes empty from exact E_FAIL despite same outer result");check(enumerationDiagnosticSuffix({}).empty(),"non-enumeration failure adds no stale record");auto copy=error;copy.byteSize=0;check(enumerationDiagnosticSuffix(copy).empty(),"unknown ABI rejected by formatting");}
void fixedCopyABI(){unsigned calls=0;const auto value=run({{EnumFailure,0,0}},calls);const auto before=value;EnumerationDiagnostic copy;check(copyEnumerationDiagnostic(value,&copy)==EnumOk&&std::memcmp(&copy,&value,32)==0,"exported32-byte numeric snapshot copies exact HRESULT fields");check(std::memcmp(&before,&value,32)==0,"diagnostic copy cannot alter retained failure state");copy.byteSize=0;auto invalidBefore=copy;check(copyEnumerationDiagnostic(value,&copy)==EnumInvalidArgument&&std::memcmp(&copy,&invalidBefore,32)==0,"incorrect ABI size fails without writing");check(copyEnumerationDiagnostic(value,nullptr)==EnumInvalidArgument,"null ABI output refused");}
template<class F>void test(const char*name,F action){try{action();std::cout<<"PASS "<<name<<'\n';}catch(const std::exception&e){++failures;std::cout<<"FAIL "<<name<<": "<<e.what()<<'\n';}}
}
int main(){test("normal empty",normalEnd);test("one item and normal end",oneAndEnd);test("E_FAIL boundary",nextFailure);test("exact error",exactFailure);test("error after match",failureAfterMatch);test("abnormal fetched",malformed);test("failed enumerator API",failedAPICall);test("null enumerator",missingPointer);test("failure with fetched",failureWithFetched);test("fixed numeric receipt",fixedNumericReceipt);test("fixed numeric export ABI",fixedCopyABI);test("fresh process result",freshChildExit);std::cout<<"checks="<<checks<<" failures="<<failures<<"; synthetic enumerator only; no COM/registry/PC\n";return failures?1:0;}
